) AS (
  VALUES 
    (517::BIGINT, 'Excelente profesora, las presentaciones son útiles, explica de forma clara en las clases y en hora de consulta ayuda mucho. Revisa justo pero no regala ni un punto. Lo pone a uno a resolver parte de ejercicios en clases. Haga los ejercicios recomendados para que le vaya bien en los quizzes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2026-01-18T00:00:00+00:00'::TIMESTAMPTZ, '1ccc6e5cdacfd168e6ad5fbe8a88a1db25e8b21bd50e7378c2925a453274c24a'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Buena profesora, explica todo bastante claro, si puede matricular con ella es una excelente opción. Califica bastante duro, por lo que le valora mas el procedimiento completo que el resultado en sí, sus presentaciones son buenas pero le tocará reforzarse con otros ejercicios externos a la clase.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, '553f4fa1b1ced1c05a57ac56c6cde1d69452ae146ff969d03687fdbaa65cf089'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'La profe explica muy bien y bastante claro, solo que no es suficiente con el material de clase, debes estudiar por tu cuenta, pero sí te da buenas bases. Sí la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'c4f86615a9ff8831a49e3d5e5ff8e07d4ddda169ad22caee16779af7ebd712fb'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Para CDI no matricule con ella, tiene presentaciones que no abarcan realmente lo importante y cuando uno le dice que casi no se ven temas en clase ella se enoja, no se interesa realmente como otros profes en dar más material de apoyo a los estudiantes, no volvería a matricular con ella, no lo vale'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '7385496fdff29f8ea57722f25e50ae6b2509fe40dedfcfe8b07c9705d4b71b43'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Si usted puede matricualar con ella, hágalo. Las clases pueden ser un poco cansadas, pero explica super bien y se preocupa porque el estudiante aprenda. Califica justo, pero siempre buscando ayudar al estudiante (claro, lo ayuda más si usted va a las clases, ya que así le demuestra su interés).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'e035defdfc55d54de87827f43f24b18e073646270f5a7de30d89019b8fee2ad4'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'no le dio 0,9 a una compañera para pasar. se deleita en quedar gente. no es profesional. se ríe cuando a alguien no le da para pasar o redondeo.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-07T00:00:00+00:00'::TIMESTAMPTZ, '0b6854b9d7381581f150ea5937c292be370aa8c93cce85a762aca1979ff3b92a'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Fui de oyente con ella y fue la mejor decisión que pude haber tomado, presentaciones super buenas, explicaciones super claras y siempre dispuesta a consultas, me arrepiento de no haber matriculado con ella pero gracias a ella pasé el curso, no se va a arrepentir de matricular, de las mejores profes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-11-30T00:00:00+00:00'::TIMESTAMPTZ, '7d11ffdff2c5345609e1b3dc924ee0ceaa0197f50a361563b868c25d8bc62b96'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'El curso es medio rudo pero con Adriana se pasa solo, deja tareas super fáciles para que uno repase y siempre sube las presentaciones para que uno pueda estudiar en la casa. 100% recomendada'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'fcf7ab8102a68b125433bb3507a7a84147ac35349326eb62daf8ac92a36e2cb1'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Discreta es complicada, pero con las tareas que deja la profe uno se mantiene al día y aprende. Aunque parece ruda, es muy buena persona si se le habla. Si da vergüenza preguntar en clase, lo mejor es anotar las dudas e ir a consulta. Eso ayuda muchísimo para pasar'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2025-07-19T00:00:00+00:00'::TIMESTAMPTZ, '90af1c6018b209f9fdc69432e5395954a7888b7e836a1f656e5f4c4487b7c967'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Senti que explico muy bien, si va a las horas de consulta le va a ayudar un monton y le pone muchas ganas al curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-15T00:00:00+00:00'::TIMESTAMPTZ, '951c3859307eb87f3f419768a937b8dd810251d05d67f293e09bdd5578e6c9a5'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Profesora increíble, no se confíe, póngale desde un inicio y Discreta va a ser un curso fácil de pasar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '717a0e5b023f0e4e100d0fb308346d13818ac8ad57375ce3034e909307017f38'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Hoy fue mi última clase de mate discreta del semestre y estoy contentisimo con mi elección Es una excelente profesora, explica muy bien, es muy amable y siempre resuelve cualquier duda. Si usted quiere pasar mate discreta, matricule con Adriana de una, pongale bonito, y va a pasar. Yo llevo 90/100s'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c6626d5d128bfab38237473518fbc9e817363f7fce35922b6eccae94ff957dc3'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Adriana es de lo mejor que puede elegir, es una bella persona, ayuda bastante y explica muy bien, deja muchas tareas que lo preparan y siempre esta dispuesta a aclarar dudas. Definitivamente la recomiendo, no se va a arrepentir.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-28T00:00:00+00:00'::TIMESTAMPTZ, '1fe5adcd847ce895a4b81083590c32234d91aae190071b5f4f4e95d17b44c42b'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Es una excelente profe, tiene mucha paciencia y explica muy claro'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '663ee6273880137130548228c2ed530ae0336c8da93fb63a688d5eae8a939de4'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Es muy buena profesora; deja mucha tarea, pero sirve para estudiar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2024-10-27T00:00:00+00:00'::TIMESTAMPTZ, '9b347c41cee24222db1be4d4079b953df9617b37b92b8ff354fdae313aa434f8'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Sin lugar a duda volvería a tomar el curso con ella, tiene mucha paciencia para aquellos estudiantes que no tienen las bases iniciales para comenzar el curso. Si eres primer ingreso y estás buscando un buen profesor, te la recomendaría sin dudarlo. Da tareas prácticamente semanales super funcionales'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-09-29T00:00:00+00:00'::TIMESTAMPTZ, 'db7a05564daadda4c2966b0b02349728c6a051ff27ab09b4d1f051e1edfc0e1e'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Excelente profe, si pueden, matriculen con ella. Es un amor de persona y como profe explica con mucha claridad. Lo unico es que explica rapido pero si pone atencion, la hace toda. Deja tareas largas pero sirven mucho para estudiar. 10/10.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2024-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'd5425958003775a95673fd1b87f4b258dd8492b95b945820f5a87a41c05c0edf'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Buena profesora, explica bastante bien y deja bastante práctica, las tareas son cortas, los quices pueden llegar a ser rudos, pero al ser la profesora de cátedra de general, los exámenes tienden a venir parecidos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '375a9493ac2ac4a44a78bf667b28368be11e908967ead802fa8d054d7454e9e7'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Explica súper bien, siempre lleva su material preparado, hace videos y deja tareas y quices, ayudando a pasar la materia un poco más fácilmente. Al ser la de cátedra lo prepara a uno con prácticas más difíciles que el exámen. Eso sí, califica súper duro y no da recesos en sus clases.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2024-06-06T00:00:00+00:00'::TIMESTAMPTZ, '2d0de5fdb7c7ff55d6ecad3c29a9d19d3de64e7f5ade5fa6ce888eb683733a83'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Si realmente quiere entender calculo lleve con ella, aparte de excelente profesora califica a favor del estudiante siempre para hacerle el curso a uno lo más fácil posible. Hace presentaciones de todos los temas super completas, definitivamente llevaría todos los cursos posibles con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e74fb25eb8fdbd01347dabdb2d8831e9373515ee6c2b7f5c144373c3f578710e'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Excelente profesora, explica super bien y los quices que hace son muy fáciles. Para los exámenes deja al estudiante super preparado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9668c0ced1eaaf1a502e2f9424f9a26a5febaa8d2dee4a7f953996618f3165a9'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'La profe es muy buena, siempre tiene su material preparado y explica muy bien, pero es muy pasiva para hablar, lo que causa que después de un tiempo la clase se vuelva muy aburrida, si usted es alguien que se distrae fácilmente no lleve con ella, pero en general es una excelente profesional'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '7124a954df153728b51f84c68e73aa2fe2775d47fa469123452f0a1006173a7f'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, '572d1de09f01fcc87c5397430c7e49f5b3a9da0cdaad05f0a722e314d7e0ab60'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'La profe es buenísima. Las clases no son tan extensas ya que manda videos para que se vean antes. SIn duda es buena opción para cualquier curso de mate, explica súper bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-22T00:00:00+00:00'::TIMESTAMPTZ, '1160d5f6a01d2df120090b840a103c2928fbed20c96d16d82f0c6ad032d8e918'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'La profesora explica muy bien la materia, sin embargo opta por hacer quices propios además de los de cátedra en vez de tareas, lo que implica que preparan bien para los quices de cátedra pero son una manera muy fácil de perder puntos, en comparación a otros profesores.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '0f2c10b312f5ff77bab81289723e1205598da529a5484425531570a9413cc700'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, '5946b91da26768b59d85f65092ba20775df83c691560a17f6ef793a73a174b75'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Explica muy claro, no deja muchas evaluaciones, califica suave y es excelente, tiene todo super claro y ayuda un monton. Es una de las mejores matricule sin miedo!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '1fa6b6326e51221586be1695c64db66e3cbe867d29d346e4993f555f37bf011f'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Cada semana hace 1 clase asincrónica donde deja un vídeo con la explicación teórica y la otra clase es sincrónica donde resuelve ejercicios y explica todo de manera clara. Excelente profesora'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, '5b00993507f100414ebfe337a440626e71eb227a85b9eeefa00fc4ce284b10b2'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Excelente profe, hace el desarrollo de los ejercicios en clase lo que facilita el entendimiento, hace pocos quices, no son muy difíciles y ayudan un montón para el examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '2473dbc94982165a43cc7d8ddf342025aecbd321e1dd64884918242275a420a0'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Virtual es una excelente opción. Da la materia en presentaciones claras y resuelve ejercicios en clases. Hace el curso más sencillo de lo que es.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '4aac87a464028cd05bf9ae410ab853ee5dafc43afb266a642b6dab8fad0c3764'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Explica muy bien la materia. Si uno tiene dudas ellas se las aclara. No es una profesora que haga vínculos con sus estudiantes, pero es muy amable y se nota el interés de que uno aprenda.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '0a20862c5a9c4711d4bf76f9be711d3c2c01b450225db801eaf2958d697256ff'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Buena la profe hace el curso mas fácil y no matado. Para virtual excelente opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '4150fa597cae791910713d39058e68d26f50aacef57b0b141d10ed3867e00da0'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-07T00:00:00+00:00'::TIMESTAMPTZ, '681da41c96f5e958a8ffcbd8d7e8d8cc294cca0ca4f3a1e23f87f627a3b26bbd'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Es de las mejores, da la materia con claridad, control total de la materia, explica siempre que alguien no entiende y da la explicación para que a uno le quede claro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'cd31000dffc65e2cf2b7e61a234c6ccb79f0fdcbf14c5cf54687b71680d7e437'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'La profe explica los ejemplos en las clases, recomiendo leerse las presentaciones antes de las clases. Igual el curso virtual no es dificil, calculadora de integrales, calculadora de derivadas, descargue wolfram crackeado y vamonos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '29acb8778fd1d01bfa925f44799667be07bacd740acd14d7d0d526eff544ea81'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'En virtual es una clase sincrónica y la otra la sube en vídeo. Explica muy bien pero solo lo justo, para los exámenes podría buscar un material extra para ayudarse. La profe es muy accesible y el curso es de ponerle atención nada más.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '7db5d1a2ce772aa6885645d8b697c47d9123149bc23936e571a9c7a81354a78a'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Es muy buena nota y explica claro, los quices que hace son EXTREMADAMENTE fáciles y son básciamente un 100 garantizado. La única cosa es que sentí que no dejaba mucha práctica (más que los quices son un regalo entonces tampoco eran mucho), pero aparte de eso es excelente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'e615df49a063129b4f13eff550e85818e9d363840fe6582c4be5cc61bf5ee559'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'La mejor profe que he tenido en el tec, siempre dispuesta a evacuar dudas y explicar cuantas veces sea necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '5f2fd324f6a4a516dcacd40247167c3a4fed838a9bde001fe7b508bcbfb90a2e'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Para virtual es lo mejor que hay. Una de las clases es sincrónica y la otra manda un vídeo resumen de la materia que la cátedra asigna para la semana. Explicando es muy buena y no tiene problema con repetir si alguien no entiende.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '79d2bcf8f7b6ba781beede7699453a9a7536d913b1194d8273c8ffba9c34b782'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '498065730f265c05aae42583464f89604a739a40c9743c19cccc4e01633858b0'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Presencial y virtual es muy buena .En ambos es SUMAMENTE clara y organizada y explica todo a detalle (puede hacerse aburrido y lentao. Definitivamente se aprende y da mucho material para practicar. Los quices son fáciles y se parece a sus ejercicios. Fui casi 4 veces y mefuebien con el mat. virtual'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '8e74528bacba3d94fca73956df7e74d1a050c57fcca6c514e1e7f4dd9680ba71'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Un poco aburrida, pero definitivamente se aprende'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '6d8409c67e4fec51ef7c77a11ab669ed447554f7d4744909847b0a09edd3f2b2'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'La profe es buena gente, pero su clase es un poco aburrida hasta el punto de que dejas de prestar atención.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '5d5dd49b6d626667c7377167bd74215a4143109b93187d2cb08b5695d1ca1bf4'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Califica suavecillo. Las clases son un toque aburridas pero explica muy bien la materia. Los ejemplos de las presentaciones son igualitos a ejercicios de examen. Hagase un favor y estudie para los quices.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-01-23T00:00:00+00:00'::TIMESTAMPTZ, '94593f267fb948eda09b96cfdffde6b73658a8207a48ae834469d8b8d0f39532'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Las clases son un poco aburridas,sin embargo hace mil ejemplos y explica muy bien.Si es un poco dura para revisar pero uno de verdad aprende.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'f6353a87a1ef1900f39f65a1e201a8fc68508a447d2d9fc4a8dae04a8305ff26'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'La profesora explica muy bien pero un poco rápido, usa presentaciones con mucho texto. Los quices son fáciles y algunos los deja para la casa. En los exámenes califica muy duro y tiene que resolver las cosas como ella quiere o si no puede llegar hasta ponerle un 0.5 /4 (aunque el resultado le dé).'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '64a6f5b642b815ce9a0fecb3c909ffd1efea9a9a12bc3a9aa5bc0c8a937ea04c'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Muy buena profesora, explica muy bien, si tenes dudas detiene la clase para aclarar la duda, super recomendada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '5507973d4816ef417887170b9772e6bb9ccf12ca698219f9eaee13737e6b7a55'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Explica bien, hace muchos ejercicios en clase y las diapositivas que usa las sube por lo que después puede repasar. Lo malo es que en los exámenes si los ejercicios no se hacen de su manera baja puntos'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'b9fc3462aeb537aaf3d5615edbe0fb06a3f8182152ecdf6a267190f96242d7d6'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'No la meta después de almuerzo, sus clases son una cuna a ciertas horas, porque habla muy bajo, apaga luces y pone el proyector. Por otro lado no son obligatorias, puede leer la materia en casa.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'fa24a1877723feec83b139af4a74d9305f3fb2edd04696b5dd0d2a7c12862095'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'La clase es aburrida, solo medio lee una presentación y hace ejercicios a la carrera. Lo bueno es que las sube, pero no regala puntos. Los examenes valen muchos puntos y los quices no tanto. Deja quices en linea o en parejas o grupos'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7df843311058d747da64803c3f32923eacbf643d170d9dddd2ad50e77f874d70'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, '204493230e670709f3ce6a0b13e3c7df9c6db110b7d1e5e14863c9261b3830da'::TEXT, ARRAY[634]::BIGINT[]),
    (517::BIGINT, 'NO se guíen por la calificación que tiene. Llega a leer diapositivas y hacer demasiados ejemplos sin ningún trasfondo, no ha terminado un ejercicio cuando empieza otro, por lo que es casi imposible preguntarle algo del ejercicio. Básicamente, usted llega a apuntar una práctica para el examen.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'f42624c792fa4042177b6a628bd019ad8c3250a35ebf0cf0e72ca27516f8682c'::TEXT, ARRAY[634]::BIGINT[]),
    (517::BIGINT, 'Muy buena profe. Hace muchos ejemplos en clase, y explica muy claramente. Casi no deja tareas, y los quizzes son bastante sencillos. Recomendada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9e343a5053f9b8e04e4d0e1c7108c6b11a9bb0f30e2683cf0b80203bd1d4b0cc'::TEXT, ARRAY[634]::BIGINT[]),
    (517::BIGINT, 'La mejor profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '26afd2569c12c046b57af172309be8722b0d0e605e0758a0ec9ffbcee37191c2'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Es aburrida pero explica bien, siempre dispuesta a ayudar. Califica normal, ni suave ni duro.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-20T00:00:00+00:00'::TIMESTAMPTZ, '487990207a6e800ae64c1ac42a3a824104f6aa19fa9bc05e775a53cc604597fa'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Es muy buena profe, las clases pueden ser un poco aburridas pero es normal en este curso. Es super buena nota en consulta, ademas explica con muchos ejemplos y super claro, lo cual ayuda demasiado en los examenes. Los quices son faciles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-16T00:00:00+00:00'::TIMESTAMPTZ, '1510ee23e1b3b5fdb9b9757876d570ef86cf6e01380a9eca05345349e7ccb933'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Super buena profe, no piense en meter con ella, explica súper bien, prepara las clases con anticipación, explica siempre con diapositivas, si uno tiene preguntas las responde al instante (con los correos también responde rápido), es un poco dura calificando porque le gusta que uno escriba TODO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'bd235e8794bd0cfcfd8a0d336fce4ee61abb6b6e3749d8511faea5607688fe73'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Explica bastante bien y hace muchos ejemplos aunque todo lo da con presentaciones, lo que puede ser un poco aburrido pero también bastante útil a la hora de estudiar. No califica fuerte, la mayoría de quices son para la casa y en parejas, no deja tareas (fuera de los quices). Recomendada'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'ee85e4c5b4d2717126dca25e859fd5a55c2ec266cafcf300ce365a11aad52c03'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'lo único malo de esta profe es que es cerrada a la hora de calificar, si no es a su manera o hace algún procedimiento extra baja puntos. Califica duro.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, '8e4f91bcd7c6f07768adf55270ddd26fde4854f2e3886d77611b42773978b881'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Es excelente como profe, explica todo demasiado claro, hace un monton de ejemplos algo que ayuda bastante para el examen. No dude en matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-08T00:00:00+00:00'::TIMESTAMPTZ, '7c4e31c425e25cedffc5f5d1ef2fbd4621f056d8f1af6fe7c68de7491a4bde2a'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Muy buena profe, aunque eso de las presentaciones aveces se hace un poco aburrido.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-29T00:00:00+00:00'::TIMESTAMPTZ, '3d5780419101e93b884753b7dc0e06387abd2a5704b52d5fdc2bc9c0379352d1'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Quices para la casa, lo que es una gran ayuda, no son difíciles. Trabaja con presentaciones y es muy tranquila, lo que podría aburrir a algunos, pero si se le presta atención, los ejemplos son buenos y la explicación es clara. Un curso relativamente fácil. Recomendada, en general. -J'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-08-04T00:00:00+00:00'::TIMESTAMPTZ, '53d903dbc120bf4c327f1bcd7a95886aa232fae14a10ae53392253e24d68c9cd'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Es buena gente y sabe demasiado de lo que explica, hace presentaciones para explicar por lo que la clase se puede volver más aburrida o tediosa de lo que ya es, pero utiliza bastantes ejemplos que ayudan a entender la materia. La mayoría de los quices los deja de tarea. Recomendada'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd6cf552f17b6dc078f9308684fd5f86e3faffbb922d4bb364344a8b5f1dd4213'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Es buena profesora y muy buena gente. pero las clases pueden resultar un poco cansadas, y si lo logras entender algo te pierdes. El curso es un poco tedioso y los ejemplos que utiliza la profesora no son como los que se evalúan en el examen por lo que entiendes en clase pero no al realizar el examen'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e6a4e83efced2dd01ae95642e5328c825a05a5e7c6d7077397b935ac1c921c40'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9c26342ec6ca847b6edcd300787dad71badbec836fb13011e9e70f6ef1e38007'::TEXT, ARRAY[935]::BIGINT[]),
    (517::BIGINT, 'Excelente profesora!'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5117dc8fe3f8d51233d57627b5cfcd96ec95830096a8ad9faa7c27fc7e49eec2'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Es ordenada y explica cada tema pero habla muy bajo y como muy monótona. A veces habla como con pereza o como si estuviera aburrida, y a veces parece que no le interesa nada a su alrededor. Clase aburrida.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '0f02a729e7d8ff84a3f13cd91792c4f5dbe6bf597aec22d31256fa0db3f37798'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'da30cc217a9841b28c4603e2459d14e314df1091e11173878de227694188a676'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Sus clases son un poco aburridas, pero en sí la profesora, es excelente, realiza bastantes ejercicios, las tareas son fáciles, hace lo posible para practicar en clase antes, del examen. Lo prepara muy bien para el parcial, si sale mal es por vago y no estudiar suficiente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '33829f1c55be040a2468a0e8a78755619d211f2642ead011b4b44fd1460d99d4'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Es buena profe. Lo único es que la clase es aburrida.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '0a6f96d865d6fc8b784709777add9f852890febfde065dcd397fdb13037d522d'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Es buena profe, se interesa que usted aprenda. A veces le da pereza hacer ciertas demostraciones, pero hace las suficientes para que entienda y a veces hace que la clase fuera un poco aburridilla. Hace tareas o quizes fáciles. La recomiendo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-11T00:00:00+00:00'::TIMESTAMPTZ, '9d545c32479ec1e3245ea304e89d33c4dccd7b3ebffa0d9df20e839f7186d990'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'La prof explica muy bien y hace varios ejemplos de un mismo tema para que se entienda, a veces le da pereza demostrar las ecuaciones pero realmente no importa porque explica todo con ejemplos, eso si si quiere entender se tiene que sentar cerca xq habla muy bajo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2017-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'f05ff681f322b156c17483dd3ec3bba5e7a8f74c75e60f9e63ab5112a7be6148'::TEXT, ARRAY[1641, 1642]::BIGINT[]),
    (517::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd7a483e454025a227a3f5063af20069a357d948df90b04fc3ce0c3910dd02b2c'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Recomendada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '26fc70a7e16948c90d40bd5fdb589295919ee16bbcc81f564da2e5d1b31faf75'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Explica bastante bien y los quices no son tan complicados pero si sirven para repasar la materia'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'ff265b1f00c297e558ec48aa4ea153b53e026bbc527c81ceb507fbc8fd260896'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Es buena profe comparada con otros inutiles. Se interesa en que usted aprenda. Lo malo es que escribe y borra la pizarra muy rápido, además explica mientras va escribiendo entonces a veces cuesta ponerle atención. Su clase da mucho sueño.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2017-06-07T00:00:00+00:00'::TIMESTAMPTZ, '9446202db3089ead3c92ce4f90e2b6e6b0a0a77751d8f40a2b13dfa9942c5589'::TEXT, ARRAY[2920]::BIGINT[]),
    (517::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-07T00:00:00+00:00'::TIMESTAMPTZ, '8e854136cbad45473771f3d7bd2728eb96eb91eaa79792d91c39412e83a62494'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Explica demasiado bien, pero las clases pueden dar un poco de sueño porque con diapositivas y luego verla a ella resolver ejercicios, califica muy rudo, casi injusto'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'c41db88e53ea58105b6959842abaabcccc18d1d27f3d6b53d3bffc66146835ed'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Es una excelente profesora. Buena gente, califica justo,explica muy muy bien, es amable si se tiene una duda, es muy responsable y bien organizada. 100% recomendada.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'de388a1cf56f87a00a5aaca110ffd082e00da1ae26319c93519e3f267eac2d9c'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Es muy puntual y explica de manera muy clara, pero a la hora de revisar los exámenes es MUY estricta.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '184545dc468bf65ec04828d0c5892966d938ea28ab8e919e9a7ab459efbccaad'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'No la recomiendo califica duro si no haces las cosas como ella quiere ,es muy aburrida y los ejercicios no son nivel examen.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '2186f041396f84dfe80ce6a244b8693549aed3246ff029300ed066dbadf21a5a'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Regular'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'cfa435f6d7569c759ceeda8a33d906e8bf83f7dc6ab3054c0d9c1d8c53b99b93'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Excelente profesora, explica muy bien. Los quices son sauves y califica un poco estricta pero lo normal.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '484d31690eadbe7aa55f183ba1261cc896f1c9d4838ea68fa0548c2fd9b778d6'::TEXT, ARRAY[1034]::BIGINT[]),
    (517::BIGINT, 'Es buena, sabe mucho pero muchas veces se enreda ella sola, su preocupación impera en salir a almorzar más que en asegurarse de que se entienda. Se apoya en los sabelotodo de la clase, para pasar rápido al tema siguiente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '3ab70e98767b975afe9bc073dbc84174a59c0255c5501c3cccffd75295a14daa'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Las clases no son tan aburridas, se interesa mucho por sus estudiantes. Se puede llegar a enrredar sola explicando algo pero no ocurre seguido y en general es un poco antés de salir, siempre culpa el hambre jaja En general muy recomendada.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '66de6160d0c47062ca06e4aa4621d408faab153781b99c0c5af4fd181532056c'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Excelente profesora , explica todo muy claro'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3fa9de364577f146ce34cb540cfc2de59eaa9970e03066b81ad89276efb78e86'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Es una excelente profesora, explica muy bien y con mucha paciencia. Realiza presentaciones con toda la materia dejando todos los temas muy claros,'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'a306422fe94711c8235bb0da16511b2d7214fcb4fe6990e8836943d4c093f5ce'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Excelente profe! Explica muy claro y lo hac las veces que sea necesario para que uno entienda y los ejemplos que usa para explicar son de exámenes anteriores por lo que en mi caso no necesitaba estudiar mas que lo del libro para el examen, ademas usa un buen sistema para los quices facil de ganarlos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'e4dea0ca2d39bc7dc12657e7c9cfb73dea604b45ab1a5678c0271076fdcbfd44'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Excelente profe y persona. Se le nota el interés por que el estudiante no solo pase, sino aprenda, explica las veces que sea necesario y es bastante clara al hacerlo. No regala ni medio punto, pero más bien cuesta no entenderle. Da mucha práctica y muchos ejemplos, muy recomendada. Califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '21444ec32a2944e96f47273bebf2fa232645bcd4bdfc4fb5a51dde2156d9a252'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'es una excelente profesora, le gusta y disfruta lo que hace. motiva al estudiante a ponerle al curso. y como perosa es una teja :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-16T00:00:00+00:00'::TIMESTAMPTZ, '6d864e5f3965f095f8f47d741d67e3c7172319322abd0c037930ab399ad8db22'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, 'Excelente profesora y persona. Ella no va a regalar la nota pero es muy accesible y se nota que le gusta enseñar. Explica muy bien. Lo único malo es que le gusta dar las clases con diapositivas (ellas las sube antes). Los quices/tareas son muy fáciles.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, '6d9ba2b66fc05e6e40755cb0a8c01c7fb89df5122c8cb3eb07b5808946e12f03'::TEXT, ARRAY[634]::BIGINT[]),
    (517::BIGINT, 'Excelente, muy ordenada y da muchos ejemplos, buena persona, de las mejores que he llevado. Recomendada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-10T00:00:00+00:00'::TIMESTAMPTZ, '0fd059cca4a0250570d650ebf7db6ccd1387111a17af357eeeba340d0f0f2e08'::TEXT, ARRAY[563]::BIGINT[]),
    (517::BIGINT, '!Excelente profesora! Una de las mejores con he llevado matemática.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2015-08-08T00:00:00+00:00'::TIMESTAMPTZ, '8e560f29c56824b655ff684ff459f9c50f893fec1d55dd51f2c80d11af2bdf0f'::TEXT, ARRAY[634]::BIGINT[]),
    (517::BIGINT, 'Excelente profesora. Se aprende bastante y es muy ordenada con todo. Si uno no entiende le vuelve a explicar de nuevo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2015-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'd7d5bb52f5445c893587878ac5aebabc30ec66527daf4374beb9d277eaa14a17'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'La recomiendo. Califica justo y explica bien. Es muy ordenada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-02T00:00:00+00:00'::TIMESTAMPTZ, '313b370e776ad1310f5359005d9087e2bd283082d4849c038b1f6a6af4066cf0'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'No hay profesora más aburrida para dar una clase que ella. En mi grupo todo el mundo se dormía y más que ella habla muy muy bajo. Siempre hacía ejercicios que ni ella entendía. No la recomiendo en lo absoluto.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'f88f55689c740f6ac39b9fcbf4381f8321c3c9b065fc2aeefe9d021c9f4531d6'::TEXT, ARRAY[605]::BIGINT[]),
    (517::BIGINT, 'Es muy buena, califica justo y las presentaciones que hace ayuda mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b5268675c1cbcba795152473d23eaad05dc63870c520ae468e69a43c07198ae9'::TEXT, ARRAY[1018]::BIGINT[]),
    (517::BIGINT, 'Excelente profesora, los ejemplos que da en clase son de exámenes pasados, muy ordenada, se toma el tiempo para preparar las lecciones y que los estudiantes entiendan. Si pudiera llevar todas las mates con ella lo haría. Recomendada 100%'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'dc8a9480060f5b9b82a8aa39a62a10d5fe57145bd0b752d1424288e6cf47429c'::TEXT, ARRAY[605]::BIGINT[]),
